import React from "react";
import { motion } from "framer-motion";
import { Sparkles, ArrowDown, Crown, MapPin, Award, Truck } from "lucide-react";
import { BRAND } from "../types";

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { staggerChildren: 0.15, delayChildren: 0.3 },
  },
};

const itemVariants = {
  hidden: { opacity: 0, y: 40 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.8, ease: "easeOut" } },
};

const features = [
  { icon: Award, text: "Premium Quality" },
  { icon: Truck, text: "Pan India Delivery" },
  { icon: Sparkles, text: "Bulk Orders" },
];

export default function Hero({ onOpenQuote }: { onOpenQuote: () => void }) {
  const scrollToCollections = () => {
    document.getElementById("collections")?.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <section id="top" className="relative min-h-screen flex items-center justify-center overflow-hidden">
      {/* Background with Ken Burns effect */}
      <motion.div
        className="absolute inset-0 bg-cover bg-center"
        style={{ backgroundImage: "url('https://images.unsplash.com/photo-1519167758481-83f550bb49b3?w=1920')" }}
        initial={{ scale: 1.1 }}
        animate={{ scale: 1 }}
        transition={{ duration: 20, ease: "easeOut" }}
      />

      {/* Gradient Overlay */}
      <div className="absolute inset-0 bg-gradient-to-b from-black/70 via-black/50 to-black/80" />

      {/* Animated Light Effects */}
      <div className="absolute inset-0 overflow-hidden">
        <motion.div
          className="absolute top-1/4 left-1/4 w-96 h-96 bg-amber-500/10 rounded-full blur-3xl"
          animate={{ x: [0, 100, 0], y: [0, 50, 0], scale: [1, 1.2, 1] }}
          transition={{ duration: 10, repeat: Infinity }}
        />
        <motion.div
          className="absolute bottom-1/4 right-1/4 w-80 h-80 bg-amber-400/10 rounded-full blur-3xl"
          animate={{ x: [0, -80, 0], y: [0, -40, 0], scale: [1.2, 1, 1.2] }}
          transition={{ duration: 8, repeat: Infinity }}
        />
      </div>

      {/* Content */}
      <div className="relative z-10 container mx-auto px-6 text-center">
        <motion.div
          variants={containerVariants}
          initial="hidden"
          animate="visible"
          className="max-w-4xl mx-auto"
        >
          {/* Location Badge */}
          <motion.div variants={itemVariants} className="flex items-center justify-center gap-4 mb-10">
            <motion.div className="h-px w-16 bg-gradient-to-r from-transparent to-amber-400" />
            <span className="flex items-center gap-2 text-sm font-medium text-amber-400 tracking-[0.2em] uppercase">
              <MapPin size={14} />
              Ludhiana, Punjab | Pan India Delivery
            </span>
            <motion.div className="h-px w-16 bg-gradient-to-l from-transparent to-amber-400" />
          </motion.div>

          {/* Main Title */}
          <motion.h1
            variants={itemVariants}
            className="text-6xl md:text-7xl lg:text-8xl font-bold text-white mb-6 tracking-tight"
            style={{ fontFamily: "Georgia, serif" }}
          >
            D SAJAWAT
          </motion.h1>

          {/* Tagline */}
          <motion.div variants={itemVariants} className="flex items-center justify-center gap-4 mb-8">
            <Crown className="text-amber-400" size={28} />
            <p className="text-2xl md:text-3xl text-amber-400 italic" style={{ fontFamily: "Georgia, serif" }}>
              {BRAND.tagline}
            </p>
          </motion.div>

          {/* Subtitle */}
          <motion.p
            variants={itemVariants}
            className="text-lg md:text-xl text-white/80 max-w-2xl mx-auto mb-12 leading-relaxed"
          >
            Premium fabrics for weddings & events. Trusted by India&apos;s top decorators with Pan India delivery.
          </motion.p>

          {/* CTA Buttons */}
          <motion.div variants={itemVariants} className="flex flex-col sm:flex-row gap-5 justify-center mb-14">
            <motion.button
              onClick={scrollToCollections}
              className="px-10 py-4 bg-gradient-to-r from-amber-400 to-amber-500 text-white font-semibold rounded-full flex items-center justify-center gap-3 text-lg shadow-2xl shadow-amber-500/30"
              whileHover={{ scale: 1.05, boxShadow: "0 20px 60px rgba(212, 175, 55, 0.4)" }}
              whileTap={{ scale: 0.98 }}
            >
              <Sparkles size={20} />
              <span>Explore Collections</span>
            </motion.button>
            <motion.button
              onClick={onOpenQuote}
              className="px-10 py-4 bg-white/10 backdrop-blur-sm border-2 border-white/30 text-white font-semibold rounded-full flex items-center justify-center gap-3 text-lg hover:bg-white hover:text-gray-900 transition-all"
              whileHover={{ scale: 1.05, backgroundColor: "rgba(255,255,255,1)", color: "#1a080a" }}
              whileTap={{ scale: 0.98 }}
            >
              Get a Quote
            </motion.button>
          </motion.div>

          {/* Feature Pills */}
          <motion.div variants={itemVariants} className="flex flex-wrap gap-4 justify-center">
            {features.map((feature, i) => (
              <motion.div
                key={feature.text}
                className="px-6 py-3 rounded-full bg-white/10 backdrop-blur-md border border-white/20 flex items-center gap-3"
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                transition={{ delay: 1 + i * 0.1 }}
                whileHover={{ scale: 1.05, backgroundColor: "rgba(255,255,255,0.2)" }}
              >
                <feature.icon size={18} className="text-amber-400" />
                <span className="text-sm font-medium text-white">{feature.text}</span>
              </motion.div>
            ))}
          </motion.div>
        </motion.div>
      </div>

      {/* Scroll Indicator */}
      <motion.div
        className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-3 cursor-pointer"
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 1.5 }}
        onClick={scrollToCollections}
      >
        <span className="text-xs tracking-[0.3em] uppercase text-white/50">Scroll</span>
        <motion.div animate={{ y: [0, 12, 0] }} transition={{ duration: 1.5, repeat: Infinity, ease: "easeInOut" }}>
          <ArrowDown size={24} className="text-amber-400" />
        </motion.div>
      </motion.div>
    </section>
  );
}
